/**
 * scripts/lib/console-bundle.js
 *
 * Single-file console bundle builder and drift checker.
 * Extracts the bundle composition logic from build-console-bundle.mjs
 * to enable both automated builds and offline integrity verification.
 */

const fs = require('node:fs');
const path = require('node:path');
const { getConsoleReleaseInfo } = require('./console-release-info.js');

const SOURCES = [
  ['nn-slug.generated.js', 'nnSlug'],
  ['nn-address.generated.js', 'nnAddress'],
  ['vendor/preact.umd.js', 'preact'],
  ['vendor/htm.umd.js', 'htm'],
  ['nn-preact-init.js', 'nnPreact'],
  ['uplot.iife.min.js', 'uPlot'],
  ['visuals.js', 'nnVisuals'],
  ['nn-icons.js', 'nnIcons'],
  ['ui-kit.js', 'nnUI'],
  ['review.js', 'nnReview'],
  ['studio.js', 'nnStudio'],
  ['nn-runtime.js', 'nnConsole'],
  ['render-procedure-stepper.js', 'nnProcedureStepper'],
];

/**
 * @typedef {{ file: string, globalName: string, src: string }} BundlePart
 */

/**
 * Compose console bundle string from parts and version.
 * @param {Array<BundlePart | [string, string, string]>} parts
 * @param {string} version
 * @returns {string}
 */
function composeConsoleBundle(parts, version) {
  const files = parts.map(p => (Array.isArray(p) ? p[0] : p.file));
  const header = `/*!
 * nn-console.bundle.js — single-file console runtime + renderers.
 * Generated by scripts/build-console-bundle.mjs — DO NOT EDIT BY HAND.
 * Version ${version}. Regenerate on every console release.
 * Composed (in dependency order): ${files.join(', ')}.
 */
`;

  const outParts = [header];
  for (const part of parts) {
    const file = Array.isArray(part) ? part[0] : part.file;
    const globalName = Array.isArray(part) ? part[1] : part.globalName;
    const src = Array.isArray(part) ? part[2] : part.src;
    outParts.push(`/* ===== ${file} (defines ${globalName}) ===== */\n` + src.trim() + '\n');
  }

  return outParts.join('\n');
}

/**
 * Builds the console bundle content, optionally writing to disk.
 * @param {string} repoRoot
 * @param {{ write?: boolean }} [options]
 * @returns {string}
 */
function buildConsoleBundle(repoRoot = process.cwd(), options = {}) {
  const consoleDir = path.join(repoRoot, 'iNNfo', 'specs', 'bluepriNNts', 'console');
  const { version } = getConsoleReleaseInfo(repoRoot);

  const parts = [];
  for (const [file, globalName] of SOURCES) {
    const filePath = path.join(consoleDir, file);
    if (!fs.existsSync(filePath)) {
      throw new Error(`Console source file not found: ${filePath}`);
    }
    const src = fs.readFileSync(filePath, 'utf8');
    parts.push({ file, globalName, src });
  }

  const content = composeConsoleBundle(parts, version);

  if (options.write) {
    const outPath = path.join(consoleDir, 'nn-console.bundle.js');
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, content, 'utf8');
  }

  return content;
}

/**
 * Checks whether the committed nn-console.bundle.js matches fresh build
 * and satisfies structural contracts (no fetch, no type=module).
 * @param {string} repoRoot
 * @returns {{ ok: boolean, errors: string[] }}
 */
function checkConsoleBundle(repoRoot = process.cwd()) {
  const errors = [];
  const consoleDir = path.join(repoRoot, 'iNNfo', 'specs', 'bluepriNNts', 'console');
  const bundlePath = path.join(consoleDir, 'nn-console.bundle.js');

  if (!fs.existsSync(bundlePath)) {
    errors.push(`Bundle file does not exist: ${bundlePath}`);
    return { ok: false, errors };
  }

  let committedContent;
  try {
    committedContent = fs.readFileSync(bundlePath, 'utf8');
  } catch (err) {
    errors.push(`Failed to read ${bundlePath}: ${err.message}`);
    return { ok: false, errors };
  }

  let freshContent;
  try {
    freshContent = buildConsoleBundle(repoRoot);
  } catch (err) {
    errors.push(`Failed to build console bundle: ${err.message}`);
    return { ok: false, errors };
  }

  if (committedContent !== freshContent) {
    errors.push(
      `nn-console.bundle.js is stale. Run \`npm run build:console\` to regenerate it.`,
    );
  }

  if (committedContent.includes('fetch(')) {
    errors.push(`nn-console.bundle.js contains disallowed call to 'fetch('`);
  }

  if (/type=["']?module["']?/.test(committedContent)) {
    errors.push(`nn-console.bundle.js contains disallowed 'type=module'`);
  }

  return {
    ok: errors.length === 0,
    errors,
  };
}

module.exports = {
  SOURCES,
  composeConsoleBundle,
  buildConsoleBundle,
  checkConsoleBundle,
};
